const adminPlusInvoiceSummary = `-- name: AdminPlusInvoiceSummary :one
SELECT CAST(COALESCE(SUM(CASE WHEN i.status = 'paid' THEN i.total_rials ELSE 0 END), 0) AS UNSIGNED) AS paid_rials,
       CAST(COALESCE(SUM(CASE WHEN i.status = 'refunded' THEN i.total_rials ELSE 0 END), 0) AS UNSIGNED) AS refunded_rials,
       CAST(COALESCE(SUM(CASE WHEN i.status = 'paid' THEN 1 ELSE 0 END), 0) AS UNSIGNED) AS paid_count
FROM plus_invoices i
JOIN users u ON u.id = i.user_id
LEFT JOIN plus_receipts r ON r.invoice_id = i.id
WHERE i.status LIKE ?
  AND IFNULL(i.gateway, '') LIKE ?
  AND i.created_at >= ? AND i.created_at < ?
  AND (IFNULL(i.reference, '') LIKE ? OR IFNULL(r.ref_id, '') LIKE ? OR IFNULL(u.mobile, '') LIKE ?)
`

type AdminPlusInvoiceSummaryParams struct {
	Status      string
	Gateway     sql.NullString
	CreatedFrom sql.NullTime
	CreatedTo   sql.NullTime
	Q           string
	QRef        string
	QMobile     sql.NullString
}

type AdminPlusInvoiceSummaryRow struct {
	PaidRials     int64
	RefundedRials int64
	PaidCount     int64
}

func (q *Queries) AdminPlusInvoiceSummary(ctx context.Context, arg AdminPlusInvoiceSummaryParams) (AdminPlusInvoiceSummaryRow, error) {
	row := q.db.QueryRowContext(ctx, adminPlusInvoiceSummary,
		arg.Status,
		arg.Gateway,
		arg.CreatedFrom,
		arg.CreatedTo,
		arg.Q,
		arg.QRef,
		arg.QMobile,
	)
	var i AdminPlusInvoiceSummaryRow
	err := row.Scan(&i.PaidRials, &i.RefundedRials, &i.PaidCount)
	return i, err
}

