const adminShiftQueuedPlusSubscriptions = `-- name: AdminShiftQueuedPlusSubscriptions :execrows
UPDATE plus_subscriptions
SET starts_at = DATE_ADD(starts_at, INTERVAL ? DAY),
    ends_at = DATE_ADD(ends_at, INTERVAL ? DAY),
    updated_at = ?
WHERE user_id = ?
  AND id <> ?
  AND status IN ('active', 'canceled')
  AND starts_at >= ?
`

type AdminShiftQueuedPlusSubscriptionsParams struct {
	Days   interface{}
	Now    sql.NullTime
	UserID uint64
	ID     uint64
	OldEnd time.Time
}

// An extension pushes the user's queued periods (starting at or after the extended period's old end) back by the
// same number of days, so periods never overlap.
func (q *Queries) AdminShiftQueuedPlusSubscriptions(ctx context.Context, arg AdminShiftQueuedPlusSubscriptionsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, adminShiftQueuedPlusSubscriptions,
		arg.Days,
		arg.Days,
		arg.Now,
		arg.UserID,
		arg.ID,
		arg.OldEnd,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

